data['states']['Telangana']['language'] = {"title": "🗣️ TELUGU - The Melodious Language!", "emoji": "🗣️", "mainText": "Telugu is called the 'Italian of the East' because it sounds SO musical! Over 75 million people speak it! 🎵", "keyFacts": ["Spoken by 75+ MILLION people! 🌍", "Called 'Italian of the East' - super melodious! 🎵", "One of the oldest Dravidian languages! 📜", "TELUGU = CHERI (salt field) + GU (from) = Language of the salt field! 💬", "Has beautiful curved script that looks like waves! 🌊", "NAMASKARAM = Hello! 🙏", "DHANYAVADAM = Thank you! 💚", "Telugu cinema (Tollywood) is HUGE - 100+ movies yearly! 🎬", "Ancient Telugu literature dates back 1,000+ years! 📚", "Famous worldwide through Telugu movies and actors! 🌟"], "coolFacts": ["Telugu is the 4th most spoken language in India! 🏆", "Tollywood (Telugu cinema) is the second-largest film industry after Hindi! 🎬", "Telugu script is so artistic - each letter looks like a piece of art! 🎨", "The language has beautiful poetry called 'Padyalu'! 📖", "Telugu actors are SUPER famous in Indian cinema! ⭐", "The language borrowed from Sanskrit and influenced other languages! 🌍", "Some Telugu words have deep spiritual meaning! 🙏", "Famous Telugu celebrities work in Hindi cinema too! 🌟"], "didYouKnow": "Telugu is the 4th most spoken language in India! Only Hindi, Spanish (worldwide), and English have more speakers! Tollywood produces almost 100 movies EVERY YEAR! 🎬", "tryThis": "Watch Telugu movies with subtitles! Or learn Telugu greetings: NAMASKARAM (hello), DHANYAVADAM (thank you), ROJULLO (good day)! 🎥", "narration": "Telugu is SUPER musical! It's called 'Italian of the East' - imagine talking and singing at the same time! 🎵\n\n75+ MILLION people speak Telugu! That's like... the entire population of Egypt! 🌍\n\nTollywood (Telugu cinema) is HUGE - 100+ movies EVERY YEAR! That's almost 2 movies per week! 🎬\n\nThe script is SO beautiful - it looks like waves and curves! 🌊\n\nTelugu has been written for over 1,000 YEARS! Ancient poets wrote beautiful verses called 'Padyalu'! 📖\n\nVocabulary is SO poetic - some words have meanings that go super deep! 🙏\n\nTelugu actors are WORLD FAMOUS! They act in Hindi movies too!\n\nNAMASKARAM (Nah-mas-KAR-um) = Hello! DHANYAVADAM (Dhan-ya-VAH-dum) = Thank you!\n\nSay these words and you're speaking one of world's most beautiful languages! 🌟"}

data['states']['Telangana']['food'] = {"title": "🍲 HYDERABADI BIRYANI - The Royal Rice Treasure!", "emoji": "🍲", "mainText": "A LEGENDARY rice dish with meat and spices layered together! Each grain of rice is infused with flavor! It's the KING of Indian rice dishes! 👑", "keyFacts": ["Biryani means 'cooked together' - rice + meat cooked together! 🍚", "Hyderabadi biryani is THE BEST in India! 👑", "Invented for royal kings (Nizams) of Hyderabad! 👑", "Takes 45-60 minutes to cook! ⏰", "Uses basmati rice - long and fragrant! 🌾", "Cooked in layers - marinated meat, then rice! 🍽️", "Saffron (expensive spice) gives it golden color! 🟡", "Each grain is separate - never mushy! ✨", "Served with raita (yogurt) and pickles! 🥒", "One of world's most famous Indian dishes! 🌍"], "coolFacts": ["Biryani was invented for Mughal emperors! 👑", "The word 'Biryani' comes from Persian! 🌏", "Dum pukht (slow cooking) is the SECRET! ⏱️", "Saffron and rose water give it fragrance! 🌹", "Different regions make biryani differently - Hyderabadi is best! 🏆", "A single biryani pot feeds 4-5 people easily! 👥", "The rice never gets mushy - each grain is PERFECT! ✨", "Biryani can be made with chicken, mutton, or vegetables! 🥘"], "didYouKnow": "Hyderabadi biryani was invented for the NIZAMS (kings) of Hyderabad! It's so special that UNESCO considers it an intangible cultural heritage! Kings ate it at royal feasts! 👑", "tryThis": "Visit a authentic Hyderabadi biryani restaurant and order a proper biryani! Eat it with raita and pickles! Or watch videos of biryani-making! 🎥", "narration": "Hyderabadi biryani is ABSOLUTELY LEGENDARY! 👑\n\nImagine - long golden rice grains mixed with tender meat, all fragrant with saffron and spices!\n\nIt was invented for the NIZAMS (kings) of Hyderabad! This is ROYAL FOOD! 👑\n\nCooks layer marinated meat and rice in a big pot - then seal it! 🔒\n\nSlow cooking (called 'dum pukht') - the flavors mix together perfectly!\n\nWhen you open the lid - WOW! Golden rice, aromatic steam, AMAZING smell! 🌟\n\nEach grain of rice is SEPARATE - not mushy! That's the art of making biryani! ✨\n\nSaffron (the most expensive spice!) gives it golden color and special fragrance! 🌹\n\nYou eat it with yogurt (raita) and pickles - the flavors are MIND-BLOWING! 🤯\n\nOne pot of biryani feeds a WHOLE family!\n\nIt's so famous that UNESCO recognizes it as part of world's cultural heritage! 🌍\n\nHyderabadi biryani is the BEST biryani in the ENTIRE WORLD! 👑"}

data['states']['Telangana']['places'] = {"title": "🕌 CHARMINAR - Four-Faced Beauty!", "emoji": "🕌", "mainText": "A STUNNING 400-year-old monument with 4 arches! It's the most iconic building in Hyderabad! 🌟", "keyFacts": ["Built in 1591 by Muhammad Quli Qutb Shah! 📜", "156 feet tall - SUPER impressive! 🏛️", "Four arches on four sides - one for each direction! 🧭", "Each arch is 21.3 meters high! 🎯", "Named after Charminar (4 minarets)! ✨", "Used as a watchtower historically! 👀", "Over 4 million visitors annually! 👥", "Surrounded by busy marketplace - action everywhere! 🛍️", "Part of UNESCO World Heritage Site area! 🌍", "Symbol of Hyderabad's identity! 🏛️"], "coolFacts": ["Built to commemorate the founding of Hyderabad! 🎉", "The architect designed it in Persian style! 🌏", "Each arch has beautiful stucco work - ART! 🎨", "The tower was used to call people to prayer! 📯", "Built with granite core and lime mortar! 🏗️", "From top, you can see the whole old city! 👁️", "The marketplace around it is 400 YEARS OLD! 🏪", "Charminar appears in Indian currency design! 💵"], "didYouKnow": "Charminar is so famous that it appears on Indian currency! It's the symbol of Hyderabad's 400-year history! Millions of people visit every year! It's an icon of India's architectural heritage! 🌟", "tryThis": "Visit Charminar early morning to avoid crowds! Climb to the top and see 360-degree views of Hyderabad! Shop at the bazaar around it for traditional items! 🛍️", "narration": "Charminar is ABSOLUTELY BEAUTIFUL! 🌟\n\n4-FACED beauty - 'Char' means 4 in Hindi, 'Minar' means tower!\n\nIt's 156 FEET TALL - built 400 YEARS AGO! 📜\n\nWhen you stand under Charminar and look UP - it's BREATHTAKING! 😍\n\nFour massive arches - one facing each direction! North, South, East, West! 🧭\n\nEach arch is 21.3 meters high - like stacking 7 tall adults! 📏\n\nBuilt in Persian architectural style - SO elegant! 🌏\n\nInside, there's a marketplace that's been ACTIVE for 400 YEARS! People are buying, selling, eating, shopping - organized CHAOS! 🛍️\n\nClimb to the top and see ENTIRE old city of Hyderabad! 👁️\n\nFrom the top, you can see how the city grew around Charminar!\n\nIt's so important that it appears on INDIAN CURRENCY! 💵\n\nOver 4 MILLION people visit every year! 👥\n\nCharminar is the HEART and SOUL of Hyderabad! 💓"}

data['states']['Telangana']['animal'] = {"title": "🐘 ASIAN ELEPHANT - Gentle Giant!", "emoji": "🐘", "mainText": "The LARGEST land animal in Asia! Weighs 5-6 tons! Super intelligent, emotional, and social! 💪", "keyFacts": ["Asian elephants weigh 4-5 TONS! 💪", "Largest land animal in Asia! 🏆", "Can live 40-50 years in wild! 📅", "Trunk has 40,000+ muscles! 💪", "Ears are HUGE - like fans! 👂", "Incredibly intelligent - can solve puzzles! 🧩", "Family-oriented - live in herds! 👨‍👩‍👧‍👦", "Communicate through rumbling sounds! 📢", "Only 3 species of wild elephants left! 😢", "Memory is LEGENDARY - never forget! 🧠"], "coolFacts": ["Trunk is like a super hand - 40,000+ muscles! 💪", "Can pick up a pea or knock down a tree! 🌳", "Asian elephants have smaller ears than African elephants! 👂", "They're vegetarian - eat 200+ kg food daily! 🥗", "Babies (calves) are called 'umbrellas' - adorable! 👶", "Elephants mourn their dead - VERY emotional! 💔", "Live in family groups led by oldest female! 👵", "Play in mud - it's like sunscreen for them! 🏊"], "didYouKnow": "Asian elephants are ENDANGERED! Only 40,000-50,000 left in wild! They're losing habitat because forests are disappearing! Many sanctuaries are trying to save them! 😢", "tryThis": "Visit an elephant sanctuary and observe elephants! See how they interact with family members! Support elephant conservation! 🐘", "narration": "Asian elephants are ABSOLUTELY AMAZING! 🐘\n\nThey're HUGE - 5-6 TONS! That's like 10 cars combined! 💪\n\nTheir trunk? 40,000+ muscles! It can pick up a tiny pea OR knock down a TREE! 🌳\n\nThey're SO intelligent - they solve puzzles, use tools, and remember things for YEARS!\n\nElephants are EMOTIONAL! They cry, celebrate, and mourn their dead! 💔\n\nThey live in family groups - mothers, daughters, sisters together! 👨‍👩‍👧‍👦\n\nCommunicate through RUMBLING sounds - like underground telephone! 📢\n\nBabies are SO CUTE - called 'calves' - they follow moms everywhere! 👶\n\nElephants love water and mud! They spray mud like sunscreen! 🏊\n\nBUT - they're ENDANGERED! Only 40,000-50,000 left! 😢\n\nForests are disappearing and elephants lose homes! We NEED to save them! 🌳\n\nSupport elephant sanctuaries! 🐘"}

data['states']['Telangana']['funFact'] = {"title": "🎉 AMAZING FUN FACTS - Telangana Treasures!", "emoji": "🎉", "mainText": "Telangana is newest Indian state (formed 2014) but has ANCIENT history! Biryani, Charminar, and pearls - it's SPECIAL! 🌟", "keyFacts": ["Telangana became a separate state in 2014! 🎉", "Famous worldwide for Hyderabadi biryani! 🍲", "Pearl capital of India - produces TONS of pearls! 💎", "Charminar is symbol of Hyderabad! 🕌", "Home to IT industry - tech hub! 💻", "Hyderabad is called 'Cyber City'! 🏙️", "Ancient kingdom ruled by Nizams (kings)! 👑", "Home to Ramoji Film City - Bollywood set! 🎬", "Produces 90% of India's diamonds! 💎", "Miracles Bazaar - one of India's oldest markets! 🛍️"], "coolFacts": ["Hyderabad doubled in population in 20 years! 📈", "Miracles Bazaar has been operating for 400+ years! 🏪", "Telangana has 1,500+ ancient temples! 🕉️", "Pearl processing happens here - world famous! 💎", "Tech companies like Microsoft, Google have offices here! 💼", "Ramoji Film City is HUGE - bigger than many cities! 🎥", "Tanks (ponds) dot the landscape - ancient water system! 💧", "Biryani Festival happens annually - HUGE celebration! 🎉"], "didYouKnow": "Hyderabad became India's 'Silicon Valley' - tons of tech companies! It went from a historical city to a MODERN TECH HUB in 20 years! 💻🌟", "tryThis": "Watch Ramoji Film City - it's like visiting a movie studio! Or visit Pearl Street to see traditional pearl trading! 🎥💎", "narration": "Telangana is a MIX of old and new! 🌟\n\nIt's the NEWEST Indian state - only became separate in 2014! 🎉\n\nBUT - it has THOUSANDS of years of history!\n\nHyderabad is now called 'Cyber City' - TONS of tech companies! 💻\n\nMicrosoft, Google, Amazon - all have offices here!\n\nBiryani - WORLD FAMOUS! Charminar - 400 years old! 🕌\n\nPearl capital - produces 90% of India's diamonds AND pearls! 💎\n\nRamoji Film City - where Indian movies are made! It's MASSIVE! 🎬\n\nMiraWalking through 400-year-old bazaars where people still trade pearls!\n\nAncient temples everywhere - 1,500+ temples in Telangana!\n\nHyderabad went from historical kingdom to TECH HUB in just 20 years!\n\nTelangana shows how India blends HISTORY with MODERN INNOVATION! 🌟"}

