data['states']['Andhra Pradesh']['food'] = {"title": "🍲 GONGURA CURRY - The Sour Surprise!", "emoji": "🍲", "mainText": "A tangy, spicy curry made from gongura leaves (sour plant)! It's UNIQUE to Andhra Pradesh and absolutely DELICIOUS! 🌶️", "keyFacts": ["Gongura leaves are SUPER sour - naturally tangy! 🍋", "Cooked with spices and usually meat! 🥘", "Andhra specialty - eaten with rice! 🍚", "Tastes different from other Indian curries! ✨", "Gongura plant grows wild in fields! 🌿", "High in vitamins - HEALTHY! 💪", "Each family has secret recipe! 👨‍🍳", "Usually eaten for lunch! 🌤️", "Pairs perfectly with hot rice! 🍛", "Regional vegetarian versions exist! 🥗"], "coolFacts": ["Gongura is naturally sour - no lemon needed! 🍋", "Only grows in certain regions of Andhra! 🌍", "Ancient Andhra kings ate gongura curry! 👑", "Gongura juice aids digestion! 💪", "Can be cooked with meat or vegetables! 🥘", "Taste is UNIQUE - tangy, spicy, peppery! 🌶️", "Street food in Andhra Pradesh! 🛣️", "Modern restaurants serve gourmet versions! 🍽️"], "didYouKnow": "Gongura curry is SO Andhra Pradesh that locals say 'Gongura rasam is Andhra Pradesh's soul'! It's mentioned in ancient texts! Every Andhra family has their own gongura recipe! 🌟", "tryThis": "Visit Andhra Pradesh and try authentic gongura curry! Or buy gongura leaves and cook at home with your parents! It's tangy, spicy, AMAZING! 🍳", "narration": "Gongura curry is UNIQUELY Andhra! 🌶️\n\nImagine - a curry that tastes SOUR without lemon!\n\nGongura leaves are naturally tangy - they grow in Andhra fields!\n\nCooks combine these sour leaves with spices - RED CHILI, MUSTARD SEEDS, GARLIC!\n\nThe result? A TANGY, SPICY, PEPPERY EXPLOSION! 🎆\n\nYou eat it with HOT RICE - the combination is MAGIC! 🍚\n\nEvery Andhra family cooks it differently - secret recipes passed down through generations! 👨‍🍳\n\nAncient Andhra KINGS ate gongura! It's been part of culture for CENTURIES!\n\nIt's SO good for you - vitamins, aids digestion, HEALTHY! 💪\n\nYou can eat it with meat or make vegetarian version!\n\nLocals say 'Gongura curry is Andhra Pradesh's SOUL'! 🌟\n\nTaste it - your taste buds will experience SOUR like never before! 🍋"}

data['states']['Andhra Pradesh']['places'] = {"title": "🕉️ TIRUPATI TEMPLE - World's Richest Temple!", "emoji": "🕉️", "mainText": "The RICHEST temple in the WORLD! Millions of pilgrims visit yearly! Ancient, spiritual, and BREATHTAKING! 🙏", "keyFacts": ["Located in Tirupati, Andhra Pradesh 📍", "Built in 10th century - 1,000+ years old! 📜", "World's richest temple! 💰", "Receives 2-3 MILLION visitors annually! 👥", "Pilgrims shave their heads as offering! 💈", "Temple revenue: 1 BILLION+ dollars yearly! 💵", "Huge gold reserves - valued in billions! 🏆", "Intricate carvings and architecture - STUNNING! 🎨", "Believed to fulfill wishes! 🙏", "Most visited Hindu temple globally! 🌍"], "coolFacts": ["The temple has more wealth than many countries! 💰", "Laddu (sweet) distribution - 1 million per day! 🍬", "Pilgrims queue 12+ hours for darshan! 👥", "Pilgrims donate gold and valuables - TONS! 🏆", "Temple has own banks to manage wealth! 🏦", "Intricate gopuram (tower) is architectural marvel! 🏛️", "Shaving ritual - over 600 barbers daily! 💈", "Temple sponsors hospitals and schools! 🏥"], "didYouKnow": "Tirupati is the WORLD'S RICHEST temple! More wealthy than many countries' governments! Over 2-3 MILLION people visit annually! It's a global pilgrimage destination! 🌟", "tryThis": "If possible, visit Tirupati Temple and experience the spiritual atmosphere! Try the famous Tirupati Laddu! Climb the hills - 300+ steps! 🙏", "narration": "Tirupati Temple is ABSOLUTELY MAGNIFICENT! 🕉️\n\n1,000+ YEARS OLD - built in 10th century!\n\nIt's the WORLD'S RICHEST TEMPLE! 💰\n\nValue? BILLIONS of dollars! Gold, jewels, donations - TONS!\n\n2-3 MILLION pilgrims visit EVERY YEAR! 👥\n\nPeople queue 12+ HOURS just to see the temple deity! That's DEVOTION! 🙏\n\nIntricate carvings on EVERY wall - architecture is ART! 🎨\n\nPilgrims shave their heads as offering - symbolizes devotion! 💈\n\nOver 600 barbers work daily - BUSY! 💇\n\nDaily laddu (sweet) distribution - 1 MILLION laddus daily! 🍬\n\nThe temple has its OWN BANKS! 🏦\n\nDonates money to hospitals, schools, charities! 💚\n\nTirupati demonstrates how faith creates MASSIVE institutions!\n\nIt's a global pilgrimage destination - people from ALL religions visit! 🌍\n\nMost visited temple on EARTH! 🌟"}

